                    out[rr][col] = marker
            # Projection spans the whole grid, stopping naturally at the
            # colored edge bars and preserving all non-background cells.
            for rr in range(h):
                if grid[rr][target] == background:
                    out[rr][target] = marker
    else:
        # Transposed construction for vertical bars on the left and right.
        for r, col in marks:
            if a <= r < b:
                target = c + (r - a)
                direct_cols = range(1, col)
